from collections import defaultdict, Counter
rows=defaultdict(list)
for line in open('/tmp/native-collect.txt'):
    if '::' not in line: continue
    tail=line.split('::',1)[1].strip()
    name=tail.split('[',1)[0]
    if name!='test_single_mcm_single_measure_obs': rows[name].append(tail)
for name, ids in sorted(rows.items(), key=lambda x:-len(x[1])):
    cats=Counter()
    for x in ids:
        for key in ('counts','expval','probs','sample','var'):
            if key in x: cats[key]+=1
    print(len(ids), name, dict(cats))
