cd /app && python3 << 'EOF'
from itertools import permutations

names = ['Alice','Bob','Charlie','David','Ethan','Frankie']
N = 6

def left(pos, k):   # k seats to the left
    return (pos - k) % N
def right(pos, k):  # k seats to the right
    return (pos + k) % N
def adj(a,b):
    d = abs(a-b)
    return d==1 or d==N-1
def across(a,b):
    return (a-b)%N == N//2

solutions = []
for perm in permutations(range(N)):
    pos = {name: perm[i] for i,name in enumerate(names)}
    # Bob sits two seats to the LEFT of Alice
    if left(pos['Alice'],2) != pos['Bob']:
        continue
    # Bob not next to Ethan
    if adj(pos['Bob'], pos['Ethan']):
        continue
    # Alice and Frankie not adjacent (rivals)
    if adj(pos['Alice'], pos['Frankie']):
        continue
    # Frankie next to at least one of David/Ethan
    if not (adj(pos['Frankie'],pos['David']) or adj(pos['Frankie'],pos['Ethan'])):
        continue
    # Clue: if Ethan across from Bob -> David two seats right of Alice
    if across(pos['Ethan'], pos['Bob']):
        if right(pos['Alice'],2) != pos['David']:
            continue
    solutions.append(perm)

print("num solutions (assignments):", len(solutions))
pairs = set()
for s in solutions:
    pos = {name: s[i] for i,name in enumerate(names)}
    c = pos['Charlie']
    l = (c-1)%N
    r = (c+1)%N
    inv = {v:k for k,v in pos.items()}
    n1, n2 = inv[l], inv[r]
    pairs.add(tuple(sorted([n1,n2])))

for p in sorted(pairs):
    print(p)
EOF

