disk = '''
//////////////////////////////////////////////////////////////////////////
// On-disk structure definitions.
//
// The MDF file format stores fixed-size little-endian structures. The
// original 2007 Win32 code wrote the in-memory structs directly to disk,
// which worked because pointers and ints were both 4 bytes. On 64-bit
// systems the in-memory unions grow to 8 bytes and directly writing them
// would corrupt the file format, so we use explicit on-disk structures
// with the original 32-bit file layout and convert on load/save.
//////////////////////////////////////////////////////////////////////////

// Must match the original file layout exactly.
static const size_t MDF_DISK_MESH_SIZE      = 36; // 5 * 4 (ints) + 4 * 4 (offset unions)
static const size_t MDF_DISK_ANIMATION_SIZE = 16; // 3 * 4 (meshId, numTimelines, timeLength(float)) + 4
static const size_t MDF_DISK_TIMELINE_SIZE  = 8;  // 4 (numKeyframes) + 4 (offset)
static const size_t MDF_DISK_KEYFRAME_SIZE  = 44; // float + Float3 + Float4 + Float3

struct MdfDiskMesh {
    unsigned int nNumVerts;
    unsigned int nNumIndices;
    unsigned int nNumJoints;
    int          hTexture;
    int          meshType;
    int          nVertsOffset;
    int          nIndicesOffset;
    int          nBindOffset;
    int          nParentOffset;
};

struct MdfDiskAnimation {
    int   hMeshId;
    int   nNumTimelines;
    float fTimeLength;
    int   nTimelineOffset;
};

struct MdfDiskTimeline {
    int nKeyFrames;
    int nKeyframeOffset;
