{
	if(m_vpMeshes || m_pData) {
		return false;
	}
	int nHeaderLength = sizeof(m_tMdfHeader);

	stream.Read(&m_tMdfHeader, nHeaderLength);

	//
	// Read the remainder of the file into a single memory pool. This mirrors
	// the original design (one malloc + one read for the whole payload).
	//
	m_nDataSize = stream.Length() - nHeaderLength;
	m_pData = (Byte*)malloc(m_nDataSize ? m_nDataSize : 1);
	stream.Read(m_pData, (int)m_nDataSize);

	// Points at the on-disk (file-layout) structures embedded in the pool.
	int dataPos = 0;

	// The file stores texture names as 32-bit offsets relative to the file
	// start. Fix them up into real memory pointers.
	if(m_tMdfHeader.nTextureCount > 0) {
		m_vpTextures = (char**)malloc(m_tMdfHeader.nTextureCount * sizeof(char*));
		int *pDiskTexOffsets = (int*)&m_pData[dataPos];
		dataPos += (int)(m_tMdfHeader.nTextureCount * sizeof(int));
		for(size_t i = 0; i < m_tMdfHeader.nTextureCount; i++) {
			m_vpTextures[i] = (char*)(m_pData + pDiskTexOffsets[i] - nHeaderLength);
		}
	}

	// Convert the on-disk mesh headers into the in-memory representation.
	if(m_tMdfHeader.nMeshCount > 0) {
		MdfDiskMesh *pDiskMeshes = (MdfDiskMesh*)&m_pData[dataPos];
		dataPos += (int)(MDF_DISK_MESH_SIZE * m_tMdfHeader.nMeshCount);

		m_vpMeshes = (TMdfMesh*)malloc(m_tMdfHeader.nMeshCount * sizeof(TMdfMesh));
		m_nMeshArrayLength = m_tMdfHeader.nMeshCount;

		for(size_t i = 0; i < m_tMdfHeader.nMeshCount; i++) {
			const MdfDiskMesh &d = pDiskMeshes[i];
			TMdfMesh &m = m_vpMeshes[i];
			ZeroMemory(&m, sizeof(TMdfMesh));

			m.nNumVerts   = d.nNumVerts;
			m.nNumIndices = d.nNumIndices;
			m.nNumJoints  = d.nNumJoints;
			m.hTexture    = d.hTexture;
			m.meshType    = d.meshType;

			m.uVtxs.pVertices = m_pData + d.nVertsOffset - nHeaderLength;
			m.uIdxs.pIndices  = (unsigned short*)(m_pData + d.nIndicesOffset - nHeaderLength);

			if(m.nNumJoints > 0) {
				m.uBnd.pBindMats   = (TMdfMatrix4*)(m_pData + d.nBindOffset - nHeaderLength);
				m.uPrnt.pParentInfo= (int*)(m_pData + d.nParentOffset - nHeaderLength);
			} else {
				m.uBnd.pBindMats   = 0;
				m.uPrnt.pParentInfo= 0;
			}
		}
	}

	// Convert the on-disk animation headers into the in-memory representation.
	if(m_tMdfHeader.nAnimCount > 0) {
		MdfDiskAnimation *pDiskAnims = (MdfDiskAnimation*)&m_pData[dataPos];
		dataPos += (int)(MDF_DISK_ANIMATION_SIZE * m_tMdfHeader.nAnimCount);

		m_vpAnimations = (TMdfAnimation*)malloc(m_tMdfHeader.nAnimCount * sizeof(TMdfAnimation));
		m_nAnimArrayLength = m_tMdfHeader.nAnimCount;

		for(size_t i = 0; i < m_tMdfHeader.nAnimCount; i++) {
			const MdfDiskAnimation &d = pDiskAnims[i];
			TMdfAnimation &a = m_vpAnimations[i];
			ZeroMemory(&a, sizeof(TMdfAnimation));

			a.hMeshId       = d.hMeshId;
			a.nNumTimelines = d.nNumTimelines;
			a.fTimeLength   = d.fTimeLength;

			MdfDiskTimeline *pDiskTimelines =
				(MdfDiskTimeline*)(m_pData + d.nTimelineOffset - nHeaderLength);

			// Convert timelines into an in-memory array.
			a.uTls.pTimeline = (TMdfTimeline*)malloc(d.nNumTimelines * sizeof(TMdfTimeline));
			for(int t = 0; t < d.nNumTimelines; t++) {
				a.uTls.pTimeline[t].nKeyFrames = pDiskTimelines[t].nKeyFrames;
				a.uTls.pTimeline[t].uKfs.pKeyframes =
					(TMdfKeyframe*)(m_pData + pDiskTimelines[t].nKeyframeOffset - nHeaderLength);
			}
		}
	}

	return true;
}

