new='''void MdfFormat::Destroy()
{
	// Clean up any additional memory and reset all the internal state to
	// default.
	//
	// Two possible owners:
	//  - Loaded files: m_pData owns a single pool that holds all geometry.
	//    The mesh/animation/timeline arrays are separate small allocations
	//    created during LoadFromStream.
	//  - Built files (Create/AddMesh/AddAnimation): each piece is its own
	//    allocation and m_pData is null.

	if(m_pData) {
		// Free the converted timeline arrays we allocated while loading.
		for(unsigned int i = 0; i < m_nAnimArrayLength; i++) {
			if(m_vpAnimations) {
				free(m_vpAnimations[i].uTls.pTimeline);
			}
		}
		free(m_vpMeshes);
		free(m_vpAnimations);
		free(m_vpTextures);
		free(m_pData);
	} else {
		// release meshes
		for(unsigned int i = 0; i < m_nMeshArrayLength; i++) {
			free(m_vpMeshes[i].uVtxs.pVertices);
			free(m_vpMeshes[i].uIdxs.pIndices);
			free(m_vpMeshes[i].uBnd.pBindMats);
			free(m_vpMeshes[i].uPrnt.pParentInfo);
		}

		// release animations
		for(unsigned int i = 0; i < m_nAnimArrayLength; i++) {

			// release timelines
			for(int t = 0; t < m_vpAnimations[i].nNumTimelines; t++) {
				// release keyframes
				free(m_vpAnimations[i].uTls.pTimeline[t].uKfs.pKeyframes);
			}
			free(m_vpAnimations[i].uTls.pTimeline);

		}

		free(m_vpMeshes);
		free(m_vpAnimations);

		// release textures
		for(unsigned i = 0; i < m_tMdfHeader.nTextureCount; i++) {
			free(m_vpTextures[i]);
		}
		free(m_vpTextures);
	}

	m_pData = 0;
	m_vpMeshes = 0;
	m_vpAnimations = 0;

	m_vpTextures = 0;
	m_tMdfHeader.nTextureCount = 0;

	m_nMeshArrayLength = 0;
	m_nAnimArrayLength = 0;
	ZeroMemory(&m_tMdfHeader, sizeof(m_tMdfHeader));
}

