#include <vector>
#include <cstdio>
#include <cstdint>
#include <chrono>
#include <random>
using namespace std;
int maximal_square_serial(const uint8_t* m, int rows, int cols){
    vector<int> dp(cols+1, 0);
    int maxsqlen=0;
    for(int i=1;i<=rows;i++){
        int prev=0;
        const uint8_t* row = m + (size_t)(i-1)*cols;
        for(int j=1;j<=cols;j++){
            int temp=dp[j];
            if(row[j-1]==1){
                int a=dp[j-1], b=prev, c=dp[j];
                int mn = a<b?a:b; mn = mn<c?mn:c;
                dp[j]=mn+1;
                if(dp[j]>maxsqlen) maxsqlen=dp[j];
            } else dp[j]=0;
            prev=temp;
        }
    }
    return maxsqlen*maxsqlen;
}
int main(){
    int n=1000;
    mt19937 rng(0);
    vector<uint8_t> m((size_t)n*n);
    for(auto&x:m) x = rng()&1;
    auto t0=chrono::high_resolution_clock::now();
    int r = maximal_square_serial(m.data(), n, n);
    auto t1=chrono::high_resolution_clock::now();
    printf("result=%d time=%.4f s\n", r, chrono::duration<double>(t1-t0).count());
    return 0;
}
