#include <cstdint>
#include <cstddef>
#include <vector>
#include <algorithm>
#include <cstdio>
#include <chrono>
#include <random>
using namespace std;

static inline int run_serial(const uint8_t* __restrict m, size_t rows, size_t cols){
    vector<int> dp(cols+1, 0);
    int best=0;
    for(size_t i=0;i<rows;i++){
        const uint8_t* __restrict row=m+i*cols;
        int prev=0;
        for(size_t j=0;j<cols;j++){
            int up=dp[j+1];
            if(row[j]==1){
                int left=dp[j];
                int mn=up<left?up:left;
                if(prev<mn) mn=prev;
                int v=mn+1;
                dp[j+1]=v;
                if(v>best) best=v;
            } else dp[j+1]=0;
            prev=up;
        }
    }
    return best;
}
int main(){
    size_t n=1000;
    mt19937 rng(1);
    vector<uint8_t> m(n*n);
    for(auto&x:m) x=rng()&1;
    // warmup
    run_serial(m.data(),n,n);
    double best=1e9;
    for(int k=0;k<50;k++){
        auto t0=chrono::high_resolution_clock::now();
        int r=run_serial(m.data(),n,n);
        auto t1=chrono::high_resolution_clock::now();
        double d=chrono::duration<double>(t1-t0).count();
        if(d<best) best=d;
        (void)r;
    }
    printf("best serial 1000x1000: %.6f s\n", best);
    return 0;
}
EOF
