new = '''## Normalizing constants / interval weights for the piecewise-exponential hull.
## Region k is [b_k, b_{k+1}] with b = (lower, z_1, ..., z_{m-1}, upper).
## The integral of exp(t_k(x)) over a region is computed analytically; regions
## with an infinite endpoint are integrable only when the line slopes away
## from the boundary (d_k < 0 to the left, d_k > 0 to the right).
.ars_hull_weights <- function(hull, lower, upper) {
  x <- hull$x; h <- hull$h; d <- hull$d
  b <- c(lower, hull$z, upper)
  w <- vapply(seq_along(x), function(k) {
    a <- b[k]; bb <- b[k + 1L]; dk <- d[k]
    if (a >= bb) return(0)
    ## integral of exp(h_k + d_k (x - x_k)) dx on [a, bb]
    ##   = exp(h_k - d_k x_k) * integral exp(d_k x) dx
    const <- h[k] - dk * x[k]
    if (abs(dk) < 1e-12) {
      return(exp(h[k]) * (bb - a))
    }
    if (is.infinite(a) || is.infinite(bb)) {
      ## at most one endpoint infinite
      if (is.infinite(a)) {
        if (dk >= 0) return(0)          ## grows to the left -> not integrable
        ## integral from -Inf to bb: exp(dk*bb)/(-dk)
        return(exp(const) * exp(dk * bb) / (-dk))
      } else {
        if (dk <= 0) return(0)          ## grows to the right -> not integrable
        ## integral from a to +Inf: exp(dk*a)/dk
        return(exp(const) * exp(dk * a) / dk)
      }
    }
    exp(const) * (exp(dk * bb) - exp(dk * a)) / dk
  }, numeric(1L))
  w[!is.finite(w) | w < 0] <- 0
  list(b = b, w = w, total = sum(w))
}

'''
