#!/usr/bin/env bash
# Audio-processing pipeline orchestrator.
#
#   ./solution.sh              -> run Python (WAV + mag.csv), then awk peak extraction
#   PEAKS_ONLY=1 ./solution.sh -> only regenerate peaks.csv from existing mag.csv via awk
set -euo pipefail

