DATA_DIR="${APP_DIR}/data"
MAG_CSV="${DATA_DIR}/mag.csv"
PEAKS_CSV="${DATA_DIR}/peaks.csv"

mkdir -p "${DATA_DIR}"

extract_peaks() {
    # Read mag.csv (frame,bin,val) and emit the true top-3 bins per frame.
    # Streamed: rows are grouped by frame; keep a running top-3 (descending).
    awk -F, '
    NR == 1 { next }                       # skip header
    $1 != cur {
        if (frame != "") flush()
        cur = $1
    }
    {
        frame = $1
        b = $2 + 0
        v = $3 + 0
        if (n < 1 || v > v1) {
            v3 = v2; b3 = b2
            v2 = v1; b2 = b1
            v1 = v;  b1 = b
        } else if (n < 2 || v > v2) {
            v3 = v2; b3 = b2
            v2 = v;  b2 = b
        } else if (n < 3 || v > v3) {
            v3 = v;  b3 = b
        }
