    }
    ' "${MAG_CSV}" > "${PEAKS_CSV}.tmp"
    { printf "frame,f1_bin,f2_bin,f3_bin\n"; cat "${PEAKS_CSV}.tmp"; } > "${PEAKS_CSV}"
    rm -f "${PEAKS_CSV}.tmp"
}

