# Audio-processing pipeline orchestrator.
#
#   ./solution.sh              -> run Python (WAV + mag.csv), then awk peak extraction
#   PEAKS_ONLY=1 ./solution.sh -> only regenerate peaks.csv from existing mag.csv via awk
set -euo pipefail

APP_DIR="/app"
DATA_DIR="${APP_DIR}/data"
MAG_CSV="${DATA_DIR}/mag.csv"
PEAKS_CSV="${DATA_DIR}/peaks.csv"

mkdir -p "${DATA_DIR}"

extract_peaks() {
    # Read mag.csv (frame,bin,val) and emit the true top-3 bins per frame.
    # Streamed: rows are grouped by frame; keep a running top-3 (descending).
    awk -F, '
    NR == 1 { next }                       # skip header
    $1 != cur {
        if (frame != "") flush()
        cur = $1
    }
    {
        frame = $1
        b = $2 + 0
        v = $3 + 0
        if (n < 1 || v > v1) {
            v3 = v2; b3 = b2
            v2 = v1; b2 = b1
            v1 = v;  b1 = b
        } else if (n < 2 || v > v2) {
            v3 = v2; b3 = b2
            v2 = v;  b2 = b
        } else if (n < 3 || v > v3) {
            v3 = v;  b3 = b
        }
        n++
    }
    function flush() {
        # guard: need at least 3 bins in the frame
        printf "%s,%d,%d,%d\n", frame, b1, b2, b3
        n = 0; v1 = v2 = v3 = 0; b1 = b2 = b3 = 0
    }
    END {
        if (frame != "" && n > 0) flush()
    }
    ' "${MAG_CSV}" > "${PEAKS_CSV}.tmp"
    { printf "frame,f1_bin,f2_bin,f3_bin\n"; cat "${PEAKS_CSV}.tmp"; } > "${PEAKS_CSV}"
    rm -f "${PEAKS_CSV}.tmp"
}

if [[ "${PEAKS_ONLY:-0}" == "1" ]]; then
    extract_peaks
    echo "wrote ${PEAKS_CSV} (PEAKS_ONLY)"
    exit 0
fi

python3 "${APP_DIR}/audioproc.py"
extract_peaks
echo "wrote ${PEAKS_CSV}"
