#pragma once

// Minimal, dependency-free JSON emitter used by the MDF -> JSON converter.
// Produces deterministic, pretty-printed output.

#include <cstdio>
#include <cstdlib>
#include <string>

namespace mdfjson {

// Format a float so that the serialized form round-trips to the same value.
inline std::string Number(float v) {
	char buf[64];
	// %.9g is the shortest precision that round-trips an IEEE-754 binary32.
	snprintf(buf, sizeof(buf), "%.9g", (double)v);
	return std::string(buf);
}

class Writer {
public:
	Writer() { out_.reserve(1 << 16); }

	void Raw(const char *s) { out_ += s; }

	void Key(const char *k) {
		NewlineIndent();
		Quote(k);
		out_ += ": ";
	}
	// Emit an object key without the trailing newline/indent (caller manages layout).
	void KeyInline(const char *k) {
		Quote(k);
		out_ += ": ";
	}

	template <typename T>
	void Value(T v) {
		out_ += std::to_string(v);
	}

	void Float(float v) { out_ += Number(v); }

	void String(const char *s) {
		Quote(s);
	}

	void OpenObject() { out_ += '{'; ++depth_; }
	void CloseObject() { --depth_; NewlineIndent(); out_ += '}'; }
	void OpenArray() { out_ += '['; ++depth_; }
	void CloseArray() { --depth_; NewlineIndent(); out_ += ']'; }

	// Arrays of scalars / short rows are emitted inline; see BeginInlineArray.
	void BeginInlineArray() { out_ += '['; inlineDepth_.push_back(true); ++depth_; }
	void EndInlineArray() { --depth_; out_ += ']'; inlineDepth_.pop_back(); }

	void Item() {
		NewlineIndent();
	}

	// Write a float array like [1, 2, 3] on a single line.
	void FloatArray(const float *v, int n) {
		out_ += '[';
		for (int i = 0; i < n; ++i) {
			if (i) out_ += ", ";
			out_ += Number(v[i]);
		}
		out_ += ']';
	}

	void IntArray(const int *v, int n) {
		out_ += '[';
		for (int i = 0; i < n; ++i) {
			if (i) out_ += ", ";
			out_ += std::to_string(v[i]);
		}
		out_ += ']';
	}

	bool SaveToFile(const char *path) const {
		FILE *fp = fopen(path, "wb");
		if (!fp) return false;
		size_t n = fwrite(out_.data(), 1, out_.size(), fp);
		fputc('\n', fp);
		fclose(fp);
		return n == out_.size();
	}

	const std::string &str() const { return out_; }

private:
	void NewlineIndent() {
		out_ += '\n';
		for (int i = 0; i < depth_; ++i) out_ += "  ";
	}

	void Quote(const char *s) {
		out_ += '"';
		for (const unsigned char *p = (const unsigned char *)s; *p; ++p) {
			switch (*p) {
				case '"':  out_ += "\\\""; break;
				case '\\': out_ += "\\\\"; break;
				case '\b': out_ += "\\b"; break;
				case '\f': out_ += "\\f"; break;
				case '\n': out_ += "\\n"; break;
				case '\r': out_ += "\\r"; break;
				case '\t': out_ += "\\t"; break;
				default:
					if (*p < 0x20) {
						char buf[8];
						snprintf(buf, sizeof(buf), "\\u%04x", *p);
						out_ += buf;
					} else {
						out_ += (char)*p;
					}
			}
		}
		out_ += '"';
	}

	std::string out_;
	int depth_ = 0;
	std::vector<bool> inlineDepth_;
};

} // namespace mdfjson
