p='MdfFormat.cpp'
s=open(p,encoding='utf-8').read()

old='''	// check for textures and set their pointer
	if(m_tMdfHeader.nTextureCount > 0) {
		m_vpTextures = (char**)&m_pData[dataPos];
		dataPos += m_tMdfHeader.nTextureCount * sizeof(int);
	}
'''
new='''	// The on-disk header stores the texture-name offsets as 32-bit ints.
	// The in-memory array of pointers is therefore the same width as the
	// int array in the file, so we temporarily alias it before converting
	// the offsets into real pointers (see fix-up loop below).
	Byte *pTextureOffsets = 0;

	// check for textures and set their pointer
	if(m_tMdfHeader.nTextureCount > 0) {
		pTextureOffsets = &m_pData[dataPos];
		m_vpTextures = (char**)&m_pData[dataPos];
		dataPos += m_tMdfHeader.nTextureCount * sizeof(int);
	}
'''
