// ---------------------------------------------------------------------------
// On-disk (serialized) structures.
//
// The MDF format is a memory-image format: in the original Win32 build the
// file layout was literally the byte image of the in-memory structs, where
// every "union { pointer; int offset; }" member occupied 4 bytes (a Win32
// pointer).  When the same structs are compiled for a 64-bit target the
// pointer members grow to 8 bytes, which changes sizeof() and silently breaks
// the file layout.
//
// To keep the on-disk format stable (and keep reading the original files), the
// serialized representation is described here explicitly with fixed-width
// fields.  Load/Save translate between these POD structs and the in-memory
// structures that use native pointers.
// ---------------------------------------------------------------------------

#pragma pack(push, 4)

/// Serialized counterpart of TMdfMesh (uses 32-bit file offsets).
struct MdfFileMesh
{
	int		nNumVerts;
	int		nNumIndices;
	int		nNumJoints;
	int		hTexture;
	int		meshType;

	int		nVtxOffset;		///< file offset of the vertex array
	int		nIdxOffset;		///< file offset of the index array
	int		nBndOffset;		///< file offset of the bind-pose matrix array
	int		nPrntOffset;	///< file offset of the parent-index array
};

/// Serialized counterpart of TMdfTimeline.
struct MdfFileTimeline
{
	int		nKeyFrames;
	int		nKfOffset;		///< file offset of the keyframe array
};

/// Serialized counterpart of TMdfAnimation.
struct MdfFileAnimation
{
	int		hMeshId;
	int		nNumTimelines;
	float	fTimeLength;
	int		nTlsOffset;		///< file offset of the timeline array
};

#pragma pack(pop)
'''
assert anchor in s
s=s.replace(anchor,addition,1)
open(p,'w',encoding='utf-8').write(s)
print("ok")
