cat > /app/MdfLib/tools/json_writer.h <<'EOF'
#pragma once

// Minimal, dependency-free JSON writer used by the MDF -> JSON converter.
//
// It tracks comma placement automatically: each element/key emits a leading
// ", " separator unless it is the first member of its container. Output is
// deterministic and pretty-printed.

#include <cstdio>
#include <string>
#include <vector>

namespace mdfjson {

// Format a float so that the serialized form round-trips to the same value.
inline std::string Number(float v) {
	char buf[64];
	// %.9g is the shortest precision that round-trips an IEEE-754 binary32.
	snprintf(buf, sizeof(buf), "%.9g", (double)v);
	return std::string(buf);
}

class Writer {
public:
	Writer() { out_.reserve(1 << 18); }

	// --- object / array structure -----------------------------------------

	void OpenObject() { Push('{'); }
	void CloseObject() { Pop(); out_ += '}'; }
	void OpenArray() { Push('['); }
	void CloseArray() { Pop(); out_ += ']'; }

	// Emit an object key. Also emits the separating comma/indent for the
	// value that follows.
	void Key(const char *k) {
		Separator();
		Quote(k);
		out_ += ": ";
	}

	// Begin the next element of an array.
	void Item() { Separator(); }

	// --- scalar values -----------------------------------------------------

	template <typename T>
	void Value(T v) { out_ += std::to_string(v); }

	void Float(float v) { out_ += Number(v); }

	void String(const char *s) { Quote(s); }

	void FloatArray(const float *v, int n) {
		out_ += '[';
		for (int i = 0; i < n; ++i) {
			if (i) out_ += ", ";
			out_ += Number(v[i]);
		}
		out_ += ']';
	}

	void IntArray(const int *v, int n) {
		out_ += '[';
		for (int i = 0; i < n; ++i) {
			if (i) out_ += ", ";
			out_ += std::to_string(v[i]);
		}
		out_ += ']';
	}

	bool SaveToFile(const char *path) const {
		FILE *fp = fopen(path, "wb");
		if (!fp) return false;
		size_t n = fwrite(out_.data(), 1, out_.size(), fp);
		bool ok = (n == out_.size());
		if (ok && fputc('\n', fp) == EOF) ok = false;
		if (fclose(fp) != 0) ok = false;
		return ok;
	}

	const std::string &str() const { return out_; }

private:
	struct Frame {
		bool first; // no member emitted yet
	};

	void Push(char c) {
		if (!stack_.empty()) {
			// containers are emitted as values, so they participate in the
			// parent's separator/indent handling through Item()/Key().
		}
		out_ += c;
		stack_.push_back(Frame{true});
	}

	void Pop() {
		bool wasEmpty = stack_.back().first;
		stack_.pop_back();
		if (!wasEmpty) {
			// close bracket goes on its own indented line
			out_ += '\n';
			Indent(stack_.size());
		}
	}

	void Separator() {
		Frame &f = stack_.back();
		if (f.first) {
			f.first = false;
			out_ += '\n';
		} else {
			out_ += ",\n";
		}
		Indent(stack_.size());
	}

	void Indent(size_t depth) {
		for (size_t i = 0; i < depth; ++i) out_ += "  ";
	}

	void Quote(const char *s) {
		out_ += '"';
		for (const unsigned char *p = (const unsigned char *)s; *p; ++p) {
			switch (*p) {
				case '"':  out_ += "\\\""; break;
				case '\\': out_ += "\\\\"; break;
				case '\b': out_ += "\\b"; break;
				case '\f': out_ += "\\f"; break;
				case '\n': out_ += "\\n"; break;
				case '\r': out_ += "\\r"; break;
				case '\t': out_ += "\\t"; break;
				default:
					if (*p < 0x20) {
						char buf[8];
						snprintf(buf, sizeof(buf), "\\u%04x", *p);
						out_ += buf;
					} else {
						out_ += (char)*p;
					}
			}
		}
		out_ += '"';
	}

	std::string out_;
	std::vector<Frame> stack_;
};

} // namespace mdfjson
